<script setup>import{computed,onMounted,ref}from'vue';import{request}from'../api';const data=ref({batches:[],events:[],recalls:[]}),msg=ref('');const quarantine=computed(()=>data.value.batches.filter(x=>x.status==='QUARANTINE').length);async function load(){try{data.value=await request('/api/trace-ops/dashboard?organizationCode=ZH-SH')}catch(e){msg.value=e.message}}async function create(){try{await request('/api/trace-ops/batches',{method:'POST',body:JSON.stringify({organizationCode:'ZH-SH',batchNo:'LOT-'+Date.now(),materialCode:'MAT-100',batchType:'FINISHED',quantity:100,productionDate:'2026-09-01',expiryDate:'2027-09-01'})});msg.value='批次已建立并进入质量待检区';await load()}catch(e){msg.value=e.message}}onMounted(load)</script>
<template><section class="head"><div><small>END-TO-END TRACEABILITY</small><h3>批次谱系与召回中心</h3><p>贯通批次身份、质量放行、投入产出、物流事件和召回影响范围。</p></div><button @click="create">建立生产批次</button></section><p class="msg" v-if="msg">{{msg}}</p><section class="metrics"><article><span>批次总数</span><b>{{data.batches.length}}</b><small>原料至成品</small></article><article><span>质量待检</span><b>{{quarantine}}</b><small>禁止仓储销售</small></article><article><span>召回任务</span><b>{{data.recalls.filter(x=>x.status!=='CLOSED').length}}</b><small>正反向影响分析</small></article></section><section class="board"><article><header><h4>批次状态</h4><button @click="load">刷新</button></header><div class="line" v-for="x in data.batches" :key="x.id"><span class="code">{{x.batchType.slice(0,2)}}</span><div><b>{{x.batchNo}}</b><small>{{x.materialCode}} · {{x.allocatedQuantity}} / {{x.quantity}}</small></div><em>{{x.status}}</em></div><p v-if="!data.batches.length">暂无专业追溯批次。</p></article><article><header><h4>事件链</h4><span>不可重复事件号</span></header><div class="line" v-for="x in data.events" :key="x.id"><span class="node"></span><div><b>{{x.eventType}}</b><small>{{x.location}} · {{x.businessRef}}</small></div><em>{{x.occurredAt?.slice(0,16)}}</em></div><p v-if="!data.events.length">批次放行后可登记仓储与销售事件。</p></article></section></template>
<style scoped>.head{padding:27px 30px;border-radius:14px;background:#29353a;color:#fff;display:flex;justify-content:space-between;align-items:end}.head small{color:#a9c4c9;letter-spacing:1.4px}.head h3{font-size:25px;margin:8px 0}.head p{margin:0;color:#cfdddf}.head button{border:0;border-radius:8px;background:#d5a954;color:#243237;padding:11px 17px;font-weight:700}.msg{padding:10px 14px;background:#f2f7f7;border-left:3px solid #4a858d}.metrics{display:grid;grid-template-columns:repeat(3,1fr);gap:14px;margin:16px 0}.metrics article,.board article{background:white;border:1px solid #dce5e6;border-radius:12px;padding:18px}.metrics span,.metrics small{display:block;color:#65777a}.metrics b{display:block;font-size:28px;margin:8px 0}.board{display:grid;grid-template-columns:1fr 1fr;gap:16px}.board header,.line{display:flex;align-items:center;justify-content:space-between}.board header{border-bottom:1px solid #e8eeee;padding-bottom:12px}.board header button{border:0;background:transparent;color:#347983}.line{gap:10px;padding:14px 0;border-bottom:1px solid #edf1f1}.line div{flex:1}.line small{display:block;color:#718083;margin-top:4px}.line em{font-style:normal;font-size:12px;color:#41757c}.code{width:31px;height:31px;display:grid;place-items:center;border-radius:7px;background:#dbeaec;color:#356e76;font-size:11px;font-weight:800}.node{width:9px;height:9px;border-radius:50%;background:#d5a954}@media(max-width:800px){.head{align-items:start;flex-direction:column;gap:20px}.metrics,.board{grid-template-columns:1fr}}</style>
